```

---

### Step 2: The Code (`index.js`)

```javascript
// Import required classes from discord.js
const { Client, GatewayIntentBits, Events } = require('discord.js');

// Create a new client instance with necessary intents
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent, // Required to read the text of messages
  ],
});

// Event: When the bot is ready
client.once(Events.ClientReady, (readyClient) => {
  console.log(`Ready! Logged in as ${readyClient.user.tag}`);
});

// Event: Listen for messages
client.on(Events.MessageCreate, async (message) => {
  // Ignore messages sent by bots to prevent infinite loops
  if (message.author.bot) return;

  // Check if the message content is "ping" (case-insensitive)
  if (message.content.trim().toLowerCase() === 'ping') {
    await message.reply('pong');
  }
});

// Log in using your bot's token (replace with your actual token)
client.login('YOUR_BOT_TOKEN_HERE');
```

---

### Step 3: Important Discord Developer Portal Settings

1. Go to the [Discord Developer Portal](https://discord.com/developers/applications).
2. Select your application and go to the **Bot** tab.
3. Under **Privileged Gateway Intents**, enable **Message Content Intent** (this allows the bot to read the word "ping").
4. Copy your bot token and paste it into `client.login('YOUR_TOKEN')` (or preferably use a `.env` file to keep it private).

Run your bot with:
```bash
node index.js
```

